struct BindingResourceTransfer {
    static_assert(0 <= 1,
                  "Record must be at most one of is_cmd, extensible, and chained.");
    bool hasNextInChain;

    ObjectId buffer;
    uint64_t offset;
    uint64_t size;
    ObjectId sampler;
    ObjectId textureView;

    BindingResourceTransfer() = default;
    BindingResourceTransfer(const BindingResourceTransfer&) = default;
    BindingResourceTransfer(BindingResourceTransfer&&) = default;

    [[noreturn]] BindingResourceTransfer(const volatile BindingResourceTransfer& other) {
        DAWN_UNREACHABLE();
    }
    [[noreturn]] BindingResourceTransfer(volatile BindingResourceTransfer&& other) {
        DAWN_UNREACHABLE();
    }
    [[noreturn]] BindingResourceTransfer(const volatile BindingResourceTransfer&& other) {
        DAWN_UNREACHABLE();
    }
    [[noreturn]] BindingResourceTransfer& operator=(const volatile BindingResourceTransfer& other) {
        DAWN_UNREACHABLE();
    }
};


[[nodiscard]] size_t BindingResourceGetExtraRequiredSize([[maybe_unused]] const BindingResource& record) {
    size_t result = 0;

    const ChainedStruct* next = record.nextInChain;
    while (next != nullptr) {
        switch (next->sType) {
            default: {
                result += WireAlignSizeof<DawnInjectedInvalidSTypeTransfer>();
                break;
            }
        }
        next = next->nextInChain;
    }
    return result;
}
// GetExtraRequiredSize isn't used for structures that are value members of other structures
// because we assume they cannot contain pointers themselves.
DAWN_UNUSED_FUNC(BindingResourceGetExtraRequiredSize);

WireResult BindingResourceSerialize(
    const BindingResource& record,
    volatile BindingResourceTransfer* transfer,
    [[maybe_unused]] SerializeBuffer* buffer, const ObjectIdProvider& provider) {

    const ChainedStruct* next = record.nextInChain;
    transfer->hasNextInChain = false;
    while (next != nullptr) {
        transfer->hasNextInChain = true;
        switch (next->sType) {
            default: {
                // Invalid enum. Serialize just the invalid sType for validation purposes.
                ::dawn::WarningLog() << "Unknown sType " << static_cast<uint32_t>(next->sType) << " discarded.";

                volatile DawnInjectedInvalidSTypeTransfer* chainTransfer;
                WIRE_TRY(buffer->Next(&chainTransfer));
                chainTransfer->chain.sType = wgpu::SType::DawnInjectedInvalidSType;
                chainTransfer->chain.hasNext = next->nextInChain != nullptr;
                chainTransfer->invalidSType = next->sType;
                break;
            }
        }
        next = next->nextInChain;
    }

    WIRE_TRY(provider.GetOptionalId(record.buffer, &transfer->buffer));
    WIRE_TRY(TryAssign(transfer->offset, record.offset));
    WIRE_TRY(TryAssign(transfer->size, record.size));
    WIRE_TRY(provider.GetOptionalId(record.sampler, &transfer->sampler));
    WIRE_TRY(provider.GetOptionalId(record.textureView, &transfer->textureView));

    return WireResult::Success;
}
DAWN_UNUSED_FUNC(BindingResourceSerialize);

WireResult BindingResourceDeserialize(
    BindingResource* record,
    const volatile BindingResourceTransfer* transfer,
    DeserializeBuffer* deserializeBuffer,
    [[maybe_unused]] DeserializeAllocator* allocator, const ObjectIdResolver& resolver) {

    ChainedStruct const** outChainNext = &record->nextInChain;
    bool hasNext = transfer->hasNextInChain;
    while (hasNext) {
        const volatile ChainedStructTransfer* header;
        WIRE_TRY(deserializeBuffer->Peek(&header));
        wgpu::SType sType = header->sType;
        hasNext = header->hasNext;

        switch (sType) {
            case wgpu::SType::DawnInjectedInvalidSType: {
                const volatile DawnInjectedInvalidSTypeTransfer* chainTransfer;
                WIRE_TRY(deserializeBuffer->Read(&chainTransfer));

                DawnInjectedInvalidSType* typedOutStruct;
                WIRE_TRY(GetSpace(allocator, &typedOutStruct));
                typedOutStruct->sType = sType;
                typedOutStruct->nextInChain = nullptr;
                WIRE_TRY(DawnInjectedInvalidSTypeDeserialize(typedOutStruct, chainTransfer,
                                              deserializeBuffer, allocator, resolver));
                *outChainNext = typedOutStruct;
                outChainNext = &typedOutStruct->nextInChain;
                break;
            }
            default: {
                return WireResult::FatalError;
            }
        }
    }
    *outChainNext = nullptr;

    WIRE_TRY(resolver.GetOptionalFromId(transfer->buffer, &record->buffer));
    WIRE_TRY(TryAssign(record->offset, transfer->offset));
    WIRE_TRY(TryAssign(record->size, transfer->size));
    WIRE_TRY(resolver.GetOptionalFromId(transfer->sampler, &record->sampler));
    WIRE_TRY(resolver.GetOptionalFromId(transfer->textureView, &record->textureView));

    return WireResult::Success;
}
DAWN_UNUSED_FUNC(BindingResourceDeserialize);
